public edit TFMTableName tableOverride(boolean _set, TableName _tableName)
{
    TableName tblName;

    if (_set)
    {
        this.ClassOverrideID = className2Id(_tableName);

    }
    tblName = TFMDisplayLineOverride::classId2Attribute(this.ClassOverrideID);

    return tblName;
}

public static void lookupDisplayClasses(FormControl _callingControl, int _overrideCls = classnum(TFMXMLFormat))
{
    SysTableLookup					sysTableLookup  = SysTableLookup::newParameters(tablenum(TFMDocumentTmpHandlerLookup), _callingControl);
    classId							classId;
    List							attributeClasses = TFMDisplayLineOverride::getListOfAttributeClasses(_overrideCls);
    ListEnumerator					lEnum = attributeClasses.getEnumerator();
    TFMDocumentTmpHandlerLookup     tmpLookup;

    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,className),true);
    sysTableLookup.addLookupfield(fieldNum(TFMDocumentTmpHandlerLookup,Description));

    tmpLookup.setTmp();

    while (lEnum.moveNext())
    {
        classId = lEnum.current();

        tmpLookup.Description = TFMDisplayLineOverride::classId2Attribute(classId);
        if (!tmpLookup.Description)
        {
            continue;
        }
        tmpLookup.ClassName = classId2Name(classId);
        tmpLookup.insert();
    }
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}

static List getListOfAttributeClasses(int _overrideCls = classnum(TFMXMLFormat))
{
    SysDictClass                    dictClass;
    List                            classList;

    dictClass    = new SysDictClass(_overrideCls);
    classList = dictClass.extendedBy();

    return classList;

}

public static TableName classId2TableName(ClassId _classID)
{
    DictClass               dictClass   = new SysDictClass(_classID);
    Object                  attributeCls = dictClass ? dictClass.getAttribute(classStr(TFMTableNameAttribute)) : null;
    TFMTableNameAttribute   attr;        
    str                     ret = '';
    if (attributeCls && attributeCls is TFMTableNameAttribute)
    {
        attr = attributeCls;
        return attr.parmTableName();            
    }
    return ret;
}

public static str classId2Attribute(ClassId _classID, boolean _onlyTableName = false)
{
    DictClass               dictClass   = new SysDictClass(_classID);
    Object                  attributeCls = dictClass ? dictClass.getAttribute(classStr(TFMTableNameAttribute)) : null;
    TFMTableNameAttribute   attr;
    DictTable               dt;
    str                     ret;
    if (attributeCls && attributeCls is TFMTableNameAttribute)
    {
        attr = attributeCls;
        dt = new DictTable(tableName2Id(attr.parmTableName()));

        ret = dt.label() + ((attr.parmOrderType() && !_onlyTableName) ? ('/' + attr.parmOrderType() ) : '');
    }
    return ret;
}

