    public static Map FindAndExecuteFromDS(TFMPageDatasources _ds, Common _common, Map _mapWithValues)
    {
        TFMDisplayLineOverrideLines dispLineOverride;

        Map                         result = _mapWithValues;
        str							value;
        str							key;

        while select dispLineOverride order by LineNumber asc where dispLineOverride.TFMPageDataSourcesRefRecID == _ds.recId
        {

            new ExecutePermission().assert();

            key = subStr(dispLineOverride.MethodName,1,4) == 'parm' ? subStr(dispLineOverride.MethodName,5,1000) : dispLineOverride.MethodName;
            value = result.exists(key) ? result.lookup(key) : '';
            value =  (dispLineOverride.ReplaceAppend ? '' : value + ' ') + dispLineOverride.FindValue(_common);
            result.insert(key,value);
            CodeAccessPermission::revertAssert();

        }
        return result;
    }
